"use client"
import React, {useEffect, useState} from 'react'

export default function ProfilePage(){
  const [name,setName] = useState('')
  const [email,setEmail] = useState('')

  useEffect(()=>{
    async function load(){
      try{
        const res = await fetch('http://localhost:3000/api/users/me')
        if(res.ok){
          const d = await res.json()
          setName(d.name || '')
          setEmail(d.email || '')
        }
      }catch(e){}
    }
    load()
  },[])

  async function save(e:React.FormEvent){
    e.preventDefault()
    try{
      await fetch('http://localhost:3000/api/users/me',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({name,email})})
      alert('Saved')
    }catch(e){alert('Save failed')}
  }

  return (
    <div style={{maxWidth:640,margin:'40px auto',padding:24,background:'#fff',borderRadius:10}}>
      <h2>Profile</h2>
      <form onSubmit={save} style={{display:'grid',gap:12}}>
        <label>Name<input value={name} onChange={e=>setName(e.target.value)} /></label>
        <label>Email<input value={email} onChange={e=>setEmail(e.target.value)} /></label>
        <button style={{padding:'8px 12px',background:'#059669',color:'#fff',border:'none',borderRadius:6}}>Save</button>
      </form>
    </div>
  )
}
"use client"
import React from 'react'
import { useProfile } from '../../lib/hooks/useProfile'

export default function ProfilePage(){
  const {data, loading} = useProfile()
  if (loading) return <div className="skeleton h-40 rounded" />
  return (
    <div>
      <h1 className="text-2xl font-semibold mb-4">My Profile</h1>
      <div className="p-4 border rounded">
        <div><b>Name:</b> {data?.name}</div>
        <div><b>Phone:</b> {data?.phone}</div>
        <div><b>Email:</b> {data?.email}</div>
      </div>
    </div>
  )
}
